use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{fs,path::Path};
fn hash(b:impl AsRef<[u8]>)->String{format!("{:x}",Sha256::digest(b.as_ref()))}
fn function<'a>(s:&'a str, signature:&str)->&'a str{let start=s.find(signature).unwrap();let end=s[start..].find("\n    }\n").unwrap()+start+7;&s[start..end]}
fn clean_space(s:&str)->String{s.split_whitespace().collect()}
fn main(){let root=Path::new("/tmp/zopro-retained-deque-buffers");let old=fs::read_to_string(root.join("upstream-deque.rs")).unwrap();let new=fs::read_to_string(root.join("candidate-v2/vendor/crossbeam-deque-0.8.8/src/deque.rs")).unwrap();let anchors:Value=serde_json::from_slice(&fs::read(root.join("patch-anchors.json")).unwrap()).unwrap();assert_eq!(hash(&old),anchors["original_sha256"]);
let guard=anchors["guard_original"].as_str().unwrap();let mut audits=Vec::new();
for signature in ["    pub fn steal(&self) -> Steal<T> {","    pub fn steal_batch_with_limit(&self, dest: &Worker<T>, limit: usize) -> Steal<()> {","    pub fn steal_batch_with_limit_and_pop(&self, dest: &Worker<T>, limit: usize) -> Steal<T> {"]{
 let original=function(&old,signature);let candidate=function(&new,signature);let start=candidate.find("        #[cfg(zopro_retained_deque_buffers)]\n        let pinned;").unwrap();let end=candidate.find("        // Load the back index.").unwrap();assert!(end>start);let mut recovered=candidate.to_owned();recovered.replace_range(start..end,&format!("{guard}\n\n"));assert_eq!(recovered,original,"extraction/order algorithm changed in {signature}");
 let inserted=&candidate[start..end];assert!(inserted.contains("atomic::fence(Ordering::SeqCst);\n            // SAFETY:"));assert!(inserted.contains("unsafe { epoch::unprotected() }"));assert!(inserted.contains("pinned = epoch::pin();\n            &pinned"));
 if signature.contains("batch"){assert!(inserted.contains("if self.inner.retained && dest.inner.retained {"));}else{assert!(inserted.contains("if self.inner.retained {"));}
 audits.push(json!({"signature":signature,"upstream_function_sha256":hash(original),"candidate_function_sha256":hash(candidate),"after_guard_block_removal":"byte-identical upstream function"}));
}
for signature in ["    fn reserve(&self, reserve_cap: usize) {","    pub fn push(&self, task: T) {"] {assert_eq!(function(&old,signature),function(&new,signature));}
let pop=function(&new,"    pub fn pop(&self) -> Option<T> {").replace("\n                        && self.shrink_allowed()\n                    {", " {").replace("\n                            && self.shrink_allowed()\n                        {", " {");assert_eq!(clean_space(&pop),clean_space(function(&old,"    pub fn pop(&self) -> Option<T> {")));
let signature="    unsafe fn resize(&self, new_cap: usize) {";let mut resize=function(&new,signature).to_owned();let from=resize.find("        #[cfg(zopro_retained_deque_buffers)]\n        if self.inner.retained {").unwrap();let to=resize.find("        // Destroy the old buffer later.").unwrap();let retained=resize[from..to].to_owned();assert!(retained.contains("push(Atomic::from(old))"));assert!(!retained.contains("into_owned"));assert!(retained.contains("            return;"));resize.replace_range(from..to,"");assert_eq!(resize,function(&old,signature));
assert_eq!(new.matches("&& self.shrink_allowed()").count(),2);assert_eq!(new.matches("retained: retained_buffers_enabled(),").count(),2);
let after=&new[new.find("impl<T> Drop for Inner<T>").unwrap()..new.find("/// Worker queue flavor").unwrap()];assert!(after.contains("for retired in self.retired_buffers.get_mut().drain(..)"));assert!(after.contains("retired.into_owned().into_box().dealloc()"));assert_eq!(after.matches(".drop_in_place()").count(),1);assert!(new.contains("retired_buffers: UnsafeCell<Vec<Atomic<Buffer<T>>>>"));assert!(new.contains("_marker: PhantomData<*mut ()>, // !Send + !Sync"));
let old_buffer=&old[old.find("    /// Returns a pointer to the task").unwrap()..old.find("impl<T> Clone for Buffer<T>").unwrap()];let new_buffer=&new[new.find("    /// Returns a pointer to the task").unwrap()..new.find("impl<T> Clone for Buffer<T>").unwrap()];assert_eq!(old_buffer,new_buffer);
let result=json!({"status":"passed","upstream_sha256":hash(&old),"candidate_sha256":hash(&new),"methods":audits,"owner_push_reserve":"byte-identical","owner_pop":"only two shrink-admission conditions differ, whitespace-normalized upstream remainder identical","resize":"unchanged allocation/copy/publish/pin and ordinary retirement/flush body; retained branch stores shared atomic handle and returns before retirement","destruction":"only final Inner Arc drop converts retired Atomic handles to Owned, drops pending current tasks once and deallocates retired MaybeUninit arrays","guard_order":"every retained probe has the required SeqCst fence; mixed-mode batches pin unless both queues retained; reentrant normal fence retained","payload_protocol":"original read/write/slot addressing byte-identical, including upstream generic volatile-access qualification; not a full memory-model proof","bound":"both shrink sites disabled for retained queues, unchanged grow-only power-of-two capacity allocation; retired capacity sum < current capacity, arrays <2x high-water plus descriptors/metadata","scope":"Structured source preservation audit plus native/ownership model tests, not proof of the complete deque or scheduler"});fs::write(root.join("source-audit.json"),format!("{}\n",serde_json::to_string_pretty(&result).unwrap())).unwrap();println!("SOURCE_AUDIT_PASS extraction/CAS/order unchanged, fences preserved, bounded retention and final ownership conversion");}
